   106	    public BigDecimal calculateCharge(String procedureCode, PricingContext context) {
   107	        if (procedureCode == null || procedureCode.trim().isEmpty()) {
   108	            log.warn("Empty procedure code provided");
   109	            return BigDecimal.ZERO;
   110	        }
   111	        procedureCode = procedureCode.trim();
   112	
   113	        BigDecimal baseCharge = resolveBaseCharge(procedureCode);
   114	
   115	        if (baseCharge.compareTo(BigDecimal.ZERO) == 0) {
   116	            log.warn("No pricing found for procedure: {}", procedureCode);
   117	            return BigDecimal.ZERO;
   118	        }
   119	
   120	        BigDecimal adjusted = applyAdjustments(procedureCode, baseCharge, context);
   121	
   122	        BigDecimal withDiscounts = applyDiscounts(procedureCode, adjusted, context);
   123	
   124	        BigDecimal withSurcharges = applySurcharges(procedureCode, withDiscounts, context);
   125	
   126	        BigDecimal withTax = applyTax(procedureCode, withSurcharges, context);
   127	
   128	        BigDecimal rounded = roundToNearestCent(withTax);
   129	
   130	        BigDecimal final_amount = applyLegacyScript(procedureCode, rounded, context);
   131	
   132	        log.debug("Calculated charge for {}: {} -> {} -> {} -> {} -> {} -> {}",
   133	                procedureCode, baseCharge, adjusted, withDiscounts, withSurcharges, withTax, final_amount);
   134	
   135	        return final_amount;
   136	    }
