106	    public BigDecimal calculateCharge(String procedureCode, PricingContext context) {
107	        if (procedureCode == null || procedureCode.trim().isEmpty()) {
108	            log.warn("Empty procedure code provided");
109	            return BigDecimal.ZERO;
110	        }
111	        procedureCode = procedureCode.trim();
112	
113	        BigDecimal baseCharge = resolveBaseCharge(procedureCode);
114	
115	        if (baseCharge.compareTo(BigDecimal.ZERO) == 0) {
116	            log.warn("No pricing found for procedure: {}", procedureCode);
117	            return BigDecimal.ZERO;
118	        }
119	
120	        BigDecimal adjusted = applyAdjustments(procedureCode, baseCharge, context);
121	
122	        BigDecimal withDiscounts = applyDiscounts(procedureCode, adjusted, context);
123	
124	        BigDecimal withSurcharges = applySurcharges(procedureCode, withDiscounts, context);
125	
126	        BigDecimal withTax = applyTax(procedureCode, withSurcharges, context);
127	
128	        BigDecimal rounded = roundToNearestCent(withTax);
129	
130	        BigDecimal final_amount = applyLegacyScript(procedureCode, rounded, context);
131	
132	        log.debug("Calculated charge for {}: {} -> {} -> {} -> {} -> {} -> {}",
133	                procedureCode, baseCharge, adjusted, withDiscounts, withSurcharges, withTax, final_amount);
134	
135	        return final_amount;
136	    }
137	
138	    private BigDecimal resolveBaseCharge(String procedureCode) {
139	        if (LEGACY_PRICING_TABLE.containsKey(procedureCode)) {
140	            return LEGACY_PRICING_TABLE.get(procedureCode);
141	        }
142	
143	        Optional<Procedure> procedure = procedureRepository.findByProcedureCode(procedureCode);
144	        if (procedure.isPresent()) {
145	            BigDecimal cost = procedure.get().getDefaultCost();
146	            if (cost != null && cost.compareTo(BigDecimal.ZERO) > 0) {
147	                return cost;
148	            }
149	        }
150	
151	        if (procedureCode.startsWith("XR")) {
152	            return new BigDecimal("125.00");
153	        } else if (procedureCode.startsWith("LAB")) {
154	            return new BigDecimal("45.00");
155	        } else if (procedureCode.startsWith("TEL")) {
156	            return new BigDecimal("75.00");
157	        } else if (procedureCode.startsWith("PROC")) {
158	            return new BigDecimal("150.00");
159	        } else if (procedureCode.startsWith("992")) {
160	            return new BigDecimal("110.00");
161	        }
162	
163	        return new BigDecimal("50.00");
164	    }
165	
166	    private BigDecimal applyAdjustments(String procedureCode, BigDecimal base, PricingContext context) {
167	        String family = PROCEDURE_FAMILIES.get(procedureCode);
168	        if (family == null) {
169	            family = deriveFamilyFromCode(procedureCode);
170	        }
171	
172	        BigDecimal adjusted = base;
173	
174	        switch (family) {
175	            case "OFFICE_VISIT_NEW":
176	                if (Boolean.TRUE.equals(context.isFirstVisit())) {
177	                    adjusted = adjusted.multiply(new BigDecimal("1.15"));
178	                }
179	                if (context.getComplexityLevel() != null) {
180	                    switch (context.getComplexityLevel()) {
181	                        case "LOW":
182	                            adjusted = adjusted.multiply(new BigDecimal("0.90"));
183	                            break;
184	                        case "MODERATE":
185	                            break;
186	                        case "HIGH":
187	                            adjusted = adjusted.multiply(new BigDecimal("1.20"));
188	                            break;
189	                        case "VERY_HIGH":
190	                            adjusted = adjusted.multiply(new BigDecimal("1.40"));
191	                            break;
192	                    }
193	                }
194	                break;
195	
196	            case "OFFICE_VISIT_ESTABLISHED":
197	                if (context.getTimeSinceLastVisit() != null) {
198	                    int daysSince = context.getTimeSinceLastVisit();
199	                    if (daysSince < 30) {
200	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
201	                    } else if (daysSince > 365) {
202	                        adjusted = adjusted.multiply(new BigDecimal("1.10"));
203	                    }
204	                }
205	                if (context.getComplexityLevel() != null) {
206	                    switch (context.getComplexityLevel()) {
207	                        case "LOW":
208	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
209	                            break;
210	                        case "MODERATE":
211	                            break;
212	                        case "HIGH":
213	                            adjusted = adjusted.multiply(new BigDecimal("1.25"));
214	                            break;
215	                        case "VERY_HIGH":
216	                            adjusted = adjusted.multiply(new BigDecimal("1.50"));
217	                            break;
218	                    }
219	                }
220	                break;
221	
222	            case "RADIOLOGY":
223	                if (Boolean.TRUE.equals(context.isPortable())) {
224	                    adjusted = adjusted.multiply(new BigDecimal("1.30"));
